close all
clear

% to determine max shear and bending moments under moving load of 400 N

y_bar = 41.43 % mm %[output:1c2760ea]
I = 418352.209 % mm^4 %[output:3b01ec5e]

axle_offsets = [0, 176, 340, 516, 680, 856] %[output:296aeddb]

L = 1200 % length of the beam %[output:21fbbdc5]
s_values = -axle_offsets(end):1:L %[output:62682afa]
num_locations = length(s_values) % number of locations along the beam %[output:75187d0b]
% array with all x values across the beam of length L
x = 0:1:L % mm %[output:531a7b50]


% if P is the lightest freight car load

% 120.6
% 90

P_axle_1 = [162.8, 162.8, 148, 148, 226.292, 226.292] %[output:59b72bf7]
P_axle_2 = [132.66, 132.66, 120.6, 120.6, 184.3974, 184.3974] %[output:62766312]
P_axle_3 = [99, 99, 90, 90, 137.61, 137.61] %[output:2e17da7c]


[max_shear_1, max_moment_1, V_env_1, M_env_1] = sweep(P_axle_1, axle_offsets, x, L, s_values) %[output:671c8c3d] %[output:6a59db73] %[output:1332798d] %[output:325880c3]
[max_shear_2, max_moment_2, V_env_2, M_env_2] = sweep(P_axle_2, axle_offsets, x, L, s_values) %[output:3261a3bc] %[output:4c7c7baf] %[output:887c1ef0] %[output:641401ed]
[max_shear_3, max_moment_3, V_env_3, M_env_3] = sweep(P_axle_3, axle_offsets, x, L, s_values) %[output:01c3d110] %[output:3083fa97] %[output:9910d1e3] %[output:9f94d51c]

fprintf('Case 1: max shear = %.1f N, max moment = %.0f N*mm\n', max_shear_1, max_moment_1); %[output:2a08bc30]
fprintf('Case 2: max shear = %.1f N, max moment = %.0f N*mm\n', max_shear_2, max_moment_2); %[output:3a089fe5]
fprintf('Case 3: max shear = %.1f N, max moment = %.0f N*mm\n', max_shear_3, max_moment_3); %[output:2fe42b10]

figure %[output:602937a4]
hold on %[output:602937a4]
plot(x, M_env_1, DisplayName="148") %[output:602937a4]
plot(x, M_env_2, DisplayName="120.6") %[output:602937a4]
plot(x, M_env_3, DisplayName="90") %[output:602937a4]

legend %[output:602937a4]

% where does case 1 reach the max moment of case 2 and case 3

location_case_2 = 0;
location_case_3 = 0;

% case 2 on case 1: x = 367, 889
% case 3 on case 1: x = 232, 996

% peaks of case 2 and case 3
[maxM_2] = max(M_env_2) %[output:4aa4c22c]
[maxM_3] = max(M_env_3) %[output:9e86b125]

% where case 1 is at least as big as those peaks
idx2 = find(M_env_1 >= maxM_2); % random function i found
idx3 = find(M_env_1 >= maxM_3);

disp("case 2 on case 1") % take on mm less than this to account for overestimate %[output:9925eb92]
idx2(1) %[output:91d9f33e]
idx2(end) %[output:604bbb0b]

disp("case 3 on case 1") %[output:0d49a99d]
idx3(1) %[output:891e6701]
idx3(end) %[output:912080cf]

